"""Shared helpers for writing generated files to disk."""

from __future__ import annotations

import json
import stat
import sys
import time
from pathlib import Path
from typing import Any

_REPLACE_ATTEMPTS = 5
_REPLACE_RETRY_SECONDS = 0.05


def write_text_atomic(path: Path, content: str) -> None:
    """Write ``content`` to ``path``, leaving an unchanged file's mtime alone.

    Writes to a sibling ``.tmp`` file first and renames it into place so
    readers never observe a partially written file. Leaves an existing file
    untouched (including its mtime) when its content already matches, so
    unchanged outputs keep the modification times that metadata-based reuse
    checks compare.

    Newlines are written as ``\\n`` on every platform so generated bytes, and
    the snapshots and checksums derived from them, do not depend on the OS.
    """
    write_bytes_atomic(path, content.encode("utf-8"))


def write_bytes_atomic(path: Path, content: bytes) -> None:
    """Atomically write bytes unless ``path`` already has identical content."""
    try:
        metadata = path.stat()
    except FileNotFoundError:
        metadata = None
    if (
        metadata is not None
        and stat.S_ISREG(metadata.st_mode)
        and metadata.st_size == len(content)
        and path.read_bytes() == content
    ):
        return
    temporary_path = path.with_suffix(f"{path.suffix}.tmp")
    try:
        temporary_path.write_bytes(content)
    except FileNotFoundError:
        # Creating the parent only when it's missing avoids a directory
        # syscall per file; most writes land in an existing directory.
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary_path.write_bytes(content)
    _replace(temporary_path, path)


def _replace(source: Path, destination: Path) -> None:
    # On Windows, antivirus and search indexers briefly open freshly written
    # files without delete sharing, which makes the rename fail with "Access is
    # denied" until they let go.
    for attempt in range(_REPLACE_ATTEMPTS):
        try:
            source.replace(destination)
            return
        except PermissionError:
            if sys.platform != "win32" or attempt == _REPLACE_ATTEMPTS - 1:
                raise
            time.sleep(_REPLACE_RETRY_SECONDS * (attempt + 1))


def write_json_atomic(
    path: Path, value: Any, *, sort_keys: bool = True, compact: bool = False
) -> None:
    """Write ``value`` to ``path`` as UTF-8 JSON.

    Output is pretty-printed unless ``compact``, which suits internal caches
    and state that are only read back by the tool itself.
    """
    if compact:
        content = json.dumps(
            value, sort_keys=sort_keys, ensure_ascii=False, separators=(",", ":")
        )
    else:
        content = json.dumps(value, indent=2, sort_keys=sort_keys, ensure_ascii=False)
    write_text_atomic(path, content + "\n")


def json_round_trip(value: Any) -> Any:
    """Return ``value`` as reading it back from unsorted JSON yields it.

    Tuples become lists and mapping keys become strings; key order is kept.
    """
    return json.loads(json.dumps(value))
